1	import { _Tokenizer } from './Tokenizer.ts';
2	import { _defaults } from './defaults.ts';
3	import { other, block, inline } from './rules.ts';
4	import type { Token, TokensList, Tokens } from './Tokens.ts';
5	import type { MarkedOptions } from './MarkedOptions.ts';
6	
7	/**
8	 * Block Lexer
9	 */
10	export class _Lexer<ParserOutput = string, RendererOutput = string> {
11	  tokens: TokensList;
12	  options: MarkedOptions<ParserOutput, RendererOutput>;
13	  state: {
14	    inLink: boolean;
15	    inRawBlock: boolean;
16	    top: boolean;
17	  };
18	
19	  public inlineQueue: { src: string, tokens: Token[] }[];
20	
21	  private tokenizer: _Tokenizer<ParserOutput, RendererOutput>;
22	
23	  constructor(options?: MarkedOptions<ParserOutput, RendererOutput>) {
24	    // TokenList cannot be created in one go
25	    this.tokens = [] as unknown as TokensList;
26	    this.tokens.links = Object.create(null);
27	    this.options = options || _defaults;
28	    this.options.tokenizer = this.options.tokenizer || new _Tokenizer<ParserOutput, RendererOutput>();
29	    this.tokenizer = this.options.tokenizer;
30	    this.tokenizer.options = this.options;
31	    this.tokenizer.lexer = this;
32	    this.inlineQueue = [];
33	    this.state = {
34	      inLink: false,
35	      inRawBlock: false,
36	      top: true,
37	    };
38	
39	    const rules = {
40	      other,
41	      block: block.normal,
42	      inline: inline.normal,
43	    };
44	
45	    if (this.options.pedantic) {
46	      rules.block = block.pedantic;
47	      rules.inline = inline.pedantic;
48	    } else if (this.options.gfm) {
49	      rules.block = block.gfm;
50	      if (this.options.breaks) {
51	        rules.inline = inline.breaks;
52	      } else {
53	        rules.inline = inline.gfm;
54	      }
55	    }
56	    this.tokenizer.rules = rules;
57	  }
58	
59	  /**
60	   * Expose Rules
61	   */
62	  static get rules() {
63	    return {
64	      block,
65	      inline,
66	    };
67	  }
68	
69	  /**
70	   * Static Lex Method
71	   */
72	  static lex<ParserOutput = string, RendererOutput = string>(src: string, options?: MarkedOptions<ParserOutput, RendererOutput>) {
73	    const lexer = new _Lexer<ParserOutput, RendererOutput>(options);
74	    return lexer.lex(src);
75	  }
76	
77	  /**
78	   * Static Lex Inline Method
79	   */
80	  static lexInline<ParserOutput = string, RendererOutput = string>(src: string, options?: MarkedOptions<ParserOutput, RendererOutput>) {
81	    const lexer = new _Lexer<ParserOutput, RendererOutput>(options);
82	    return lexer.inlineTokens(src);
83	  }
84	
85	  /**
86	   * Preprocessing
87	   */
88	  lex(src: string) {
89	    src = src.replace(other.carriageReturn, '\n');
90	
91	    this.blockTokens(src, this.tokens);
92	
93	    for (let i = 0; i < this.inlineQueue.length; i++) {
94	      const next = this.inlineQueue[i];
95	      this.inlineTokens(next.src, next.tokens);
96	    }
97	    this.inlineQueue = [];
98	
99	    return this.tokens;
100	  }
101	
102	  /**
103	   * Lexing
104	   */
105	  blockTokens(src: string, tokens?: Token[], lastParagraphClipped?: boolean): Token[];
106	  blockTokens(src: string, tokens?: TokensList, lastParagraphClipped?: boolean): TokensList;
107	  blockTokens(src: string, tokens: Token[] = [], lastParagraphClipped = false) {
108	    if (this.options.pedantic) {
109	      src = src.replace(other.tabCharGlobal, '    ').replace(other.spaceLine, '');
110	    }
111	
112	    while (src) {
113	      let token: Tokens.Generic | undefined;
114	
115	      if (this.options.extensions?.block?.some((extTokenizer) => {
116	        if (token = extTokenizer.call({ lexer: this }, src, tokens)) {
117	          src = src.substring(token.raw.length);
118	          tokens.push(token);
119	          return true;
120	        }
121	        return false;
122	      })) {
123	        continue;
124	      }
125	
126	      // newline
127	      if (token = this.tokenizer.space(src)) {
128	        src = src.substring(token.raw.length);
129	        const lastToken = tokens.at(-1);
130	        if (token.raw.length === 1 && lastToken !== undefined) {
131	          // if there's a single \n as a spacer, it's terminating the last line,
132	          // so move it there so that we don't get unnecessary paragraph tags
133	          lastToken.raw += '\n';
134	        } else {
135	          tokens.push(token);
136	        }
137	        continue;
138	      }
139	
140	      // code
141	      if (token = this.tokenizer.code(src)) {
142	        src = src.substring(token.raw.length);
143	        const lastToken = tokens.at(-1);
144	        // An indented code block cannot interrupt a paragraph.
145	        if (lastToken?.type === 'paragraph' || lastToken?.type === 'text') {
146	          lastToken.raw += (lastToken.raw.endsWith('\n') ? '' : '\n') + token.raw;
147	          lastToken.text += '\n' + token.text;
148	          this.inlineQueue.at(-1)!.src = lastToken.text;
149	        } else {
150	          tokens.push(token);
151	        }
152	        continue;
153	      }
154	
155	      // fences
156	      if (token = this.tokenizer.fences(src)) {
157	        src = src.substring(token.raw.length);
158	        tokens.push(token);
159	        continue;
160	      }
161	
162	      // heading
163	      if (token = this.tokenizer.heading(src)) {
164	        src = src.substring(token.raw.length);
165	        tokens.push(token);
166	        continue;
167	      }
168	
169	      // hr
170	      if (token = this.tokenizer.hr(src)) {
171	        src = src.substring(token.raw.length);
172	        tokens.push(token);
173	        continue;
174	      }
175	
176	      // blockquote
177	      if (token = this.tokenizer.blockquote(src)) {
178	        src = src.substring(token.raw.length);
179	        tokens.push(token);
180	        continue;
181	      }
182	
183	      // list
184	      if (token = this.tokenizer.list(src)) {
185	        src = src.substring(token.raw.length);
186	        tokens.push(token);
187	        continue;
188	      }
189	
190	      // html
191	      if (token = this.tokenizer.html(src)) {
192	        src = src.substring(token.raw.length);
193	        tokens.push(token);
194	        continue;
195	      }
196	
197	      // def
198	      if (token = this.tokenizer.def(src)) {
199	        src = src.substring(token.raw.length);
200	        const lastToken = tokens.at(-1);
201	        if (lastToken?.type === 'paragraph' || lastToken?.type === 'text') {
202	          lastToken.raw += (lastToken.raw.endsWith('\n') ? '' : '\n') + token.raw;
203	          lastToken.text += '\n' + token.raw;
204	          this.inlineQueue.at(-1)!.src = lastToken.text;
205	        } else if (!this.tokens.links[token.tag]) {
206	          this.tokens.links[token.tag] = {
207	            href: token.href,
208	            title: token.title,
209	          };
210	          tokens.push(token);
211	        }
212	        continue;
213	      }
214	
215	      // table (gfm)
216	      if (token = this.tokenizer.table(src)) {
217	        src = src.substring(token.raw.length);
218	        tokens.push(token);
219	        continue;
220	      }
221	
222	      // lheading
223	      if (token = this.tokenizer.lheading(src)) {
224	        src = src.substring(token.raw.length);
225	        tokens.push(token);
226	        continue;
227	      }
228	
229	      // top-level paragraph
230	      // prevent paragraph consuming extensions by clipping 'src' to extension start
231	      let cutSrc = src;
232	      if (this.options.extensions?.startBlock) {
233	        let startIndex = Infinity;
234	        const tempSrc = src.slice(1);
235	        let tempStart;
236	        this.options.extensions.startBlock.forEach((getStartIndex) => {
237	          tempStart = getStartIndex.call({ lexer: this }, tempSrc);
238	          if (typeof tempStart === 'number' && tempStart >= 0) {
239	            startIndex = Math.min(startIndex, tempStart);
240	          }
241	        });
242	        if (startIndex < Infinity && startIndex >= 0) {
243	          cutSrc = src.substring(0, startIndex + 1);
244	        }
245	      }
246	      if (this.state.top && (token = this.tokenizer.paragraph(cutSrc))) {
247	        const lastToken = tokens.at(-1);
248	        if (lastParagraphClipped && lastToken?.type === 'paragraph') {
249	          lastToken.raw += (lastToken.raw.endsWith('\n') ? '' : '\n') + token.raw;
250	          lastToken.text += '\n' + token.text;
251	          this.inlineQueue.pop();
252	          this.inlineQueue.at(-1)!.src = lastToken.text;
253	        } else {
254	          tokens.push(token);
255	        }
256	        lastParagraphClipped = cutSrc.length !== src.length;
257	        src = src.substring(token.raw.length);
258	        continue;
259	      }
260	
261	      // text
262	      if (token = this.tokenizer.text(src)) {
263	        src = src.substring(token.raw.length);
264	        const lastToken = tokens.at(-1);
265	        if (lastToken?.type === 'text') {
266	          lastToken.raw += (lastToken.raw.endsWith('\n') ? '' : '\n') + token.raw;
267	          lastToken.text += '\n' + token.text;
268	          this.inlineQueue.pop();
269	          this.inlineQueue.at(-1)!.src = lastToken.text;
270	        } else {
271	          tokens.push(token);
272	        }
273	        continue;
274	      }
275	
276	      if (src) {
277	        const errMsg = 'Infinite loop on byte: ' + src.charCodeAt(0);
278	        if (this.options.silent) {
279	          console.error(errMsg);
280	          break;
281	        } else {
282	          throw new Error(errMsg);
283	        }
284	      }
285	    }
286	
287	    this.state.top = true;
288	    return tokens;
289	  }
290	
291	  inline(src: string, tokens: Token[] = []) {
292	    this.inlineQueue.push({ src, tokens });
293	    return tokens;
294	  }
295	
296	  /**
297	   * Lexing/Compiling
298	   */
299	  inlineTokens(src: string, tokens: Token[] = []): Token[] {
300	    // String with links masked to avoid interference with em and strong
301	    let maskedSrc = src;
302	    let match: RegExpExecArray | null = null;
303	
304	    // Mask out reflinks
305	    if (this.tokens.links) {
306	      const links = Object.keys(this.tokens.links);
307	      if (links.length > 0) {
308	        while ((match = this.tokenizer.rules.inline.reflinkSearch.exec(maskedSrc)) != null) {
309	          if (links.includes(match[0].slice(match[0].lastIndexOf('[') + 1, -1))) {
310	            maskedSrc = maskedSrc.slice(0, match.index)
311	              + '[' + 'a'.repeat(match[0].length - 2) + ']'
312	              + maskedSrc.slice(this.tokenizer.rules.inline.reflinkSearch.lastIndex);
313	          }
314	        }
315	      }
316	    }
317	
318	    // Mask out escaped characters
319	    while ((match = this.tokenizer.rules.inline.anyPunctuation.exec(maskedSrc)) != null) {
320	      maskedSrc = maskedSrc.slice(0, match.index) + '++' + maskedSrc.slice(this.tokenizer.rules.inline.anyPunctuation.lastIndex);
321	    }
322	
323	    // Mask out other blocks
324	    let offset;
325	    while ((match = this.tokenizer.rules.inline.blockSkip.exec(maskedSrc)) != null) {
326	      offset = match[2] ? match[2].length : 0;
327	      maskedSrc = maskedSrc.slice(0, match.index + offset) + '[' + 'a'.repeat(match[0].length - offset - 2) + ']' + maskedSrc.slice(this.tokenizer.rules.inline.blockSkip.lastIndex);
328	    }
329	
330	    // Mask out blocks from extensions
331	    maskedSrc = this.options.hooks?.emStrongMask?.call({ lexer: this }, maskedSrc) ?? maskedSrc;
332	
333	    let keepPrevChar = false;
334	    let prevChar = '';
335	    while (src) {
336	      if (!keepPrevChar) {
337	        prevChar = '';
338	      }
339	      keepPrevChar = false;
340	
341	      let token: Tokens.Generic | undefined;
342	
343	      // extensions
344	      if (this.options.extensions?.inline?.some((extTokenizer) => {
345	        if (token = extTokenizer.call({ lexer: this }, src, tokens)) {
346	          src = src.substring(token.raw.length);
347	          tokens.push(token);
348	          return true;
349	        }
350	        return false;
351	      })) {
352	        continue;
353	      }
354	
355	      // escape
356	      if (token = this.tokenizer.escape(src)) {
357	        src = src.substring(token.raw.length);
358	        tokens.push(token);
359	        continue;
360	      }
361	
362	      // tag
363	      if (token = this.tokenizer.tag(src)) {
364	        src = src.substring(token.raw.length);
365	        tokens.push(token);
366	        continue;
367	      }
368	
369	      // link
370	      if (token = this.tokenizer.link(src)) {
371	        src = src.substring(token.raw.length);
372	        tokens.push(token);
373	        continue;
374	      }
375	
376	      // reflink, nolink
377	      if (token = this.tokenizer.reflink(src, this.tokens.links)) {
378	        src = src.substring(token.raw.length);
379	        const lastToken = tokens.at(-1);
380	        if (token.type === 'text' && lastToken?.type === 'text') {
381	          lastToken.raw += token.raw;
382	          lastToken.text += token.text;
383	        } else {
384	          tokens.push(token);
385	        }
386	        continue;
387	      }
388	
389	      // em & strong
390	      if (token = this.tokenizer.emStrong(src, maskedSrc, prevChar)) {
391	        src = src.substring(token.raw.length);
392	        tokens.push(token);
393	        continue;
394	      }
395	
396	      // code
397	      if (token = this.tokenizer.codespan(src)) {
398	        src = src.substring(token.raw.length);
399	        tokens.push(token);
400	        continue;
401	      }
402	
403	      // br
404	      if (token = this.tokenizer.br(src)) {
405	        src = src.substring(token.raw.length);
406	        tokens.push(token);
407	        continue;
408	      }
409	
410	      // del (gfm)
411	      if (token = this.tokenizer.del(src, maskedSrc, prevChar)) {
412	        src = src.substring(token.raw.length);
413	        tokens.push(token);
414	        continue;
415	      }
416	
417	      // autolink
418	      if (token = this.tokenizer.autolink(src)) {
419	        src = src.substring(token.raw.length);
420	        tokens.push(token);
421	        continue;
422	      }
423	
424	      // url (gfm)
425	      if (!this.state.inLink && (token = this.tokenizer.url(src))) {
426	        src = src.substring(token.raw.length);
427	        tokens.push(token);
428	        continue;
429	      }
430	
431	      // text
432	      // prevent inlineText consuming extensions by clipping 'src' to extension start
433	      let cutSrc = src;
434	      if (this.options.extensions?.startInline) {
435	        let startIndex = Infinity;
436	        const tempSrc = src.slice(1);
437	        let tempStart;
438	        this.options.extensions.startInline.forEach((getStartIndex) => {
439	          tempStart = getStartIndex.call({ lexer: this }, tempSrc);
440	          if (typeof tempStart === 'number' && tempStart >= 0) {
441	            startIndex = Math.min(startIndex, tempStart);
442	          }
443	        });
444	        if (startIndex < Infinity && startIndex >= 0) {
445	          cutSrc = src.substring(0, startIndex + 1);
446	        }
447	      }
448	      if (token = this.tokenizer.inlineText(cutSrc)) {
449	        src = src.substring(token.raw.length);
450	        if (token.raw.slice(-1) !== '_') { // Track prevChar before string of ____ started
451	          prevChar = token.raw.slice(-1);
452	        }
453	        keepPrevChar = true;
454	        const lastToken = tokens.at(-1);
455	        if (lastToken?.type === 'text') {
456	          lastToken.raw += token.raw;
457	          lastToken.text += token.text;
458	        } else {
459	          tokens.push(token);
460	        }
461	        continue;
462	      }
463	
464	      if (src) {
465	        const errMsg = 'Infinite loop on byte: ' + src.charCodeAt(0);
466	        if (this.options.silent) {
467	          console.error(errMsg);
468	          break;
469	        } else {
470	          throw new Error(errMsg);
471	        }
472	      }
473	    }
474	
475	    return tokens;
476	  }
477	}
